from .base import EMSSInterface
import time


class CellTraceManager(EMSSInterface):
    """
    EMSsim keywords related to Cell Tracing
    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'  # 'TEST CASE' 'GLOBAL'

    def __init__(self):
        super(CellTraceManager, self).__init__()

    def cell_trace_activate(self, interfaces, vendor="", port="", enb_id=None, bts_id=None, alias=None):
        """
        Activates Cell Trace on eNB

        :param interfaces: comma or space separated string of interfaces to be traced.
            Comma separated list of following values:
            * s: S1AP interface (eNodeB <-> MME)
            * x: X2AP interface (eNodeB <-> neighbor eNodeB)
            * u: Uu interface   (enodeb <-> UE)
        :param vendor: flag controls vendor specific tracing. Currently only MAC layer TA (Timing Advance) messages.
            By default TA tracing is disabled.
        :param port: port number of trace collecting entity.
            The option is needed only in case when default port number should be overwriten.
            Default port number is calculated from formula: port = 49000 + BTS_ID.
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +---------------------+-------+
        |          Examples           |
        +=====================+=======+
        | cell trace activate | s x u |
        +---------------------+-------+
        | cell trace activate | s,x,u |
        +---------------------+-------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        interfaces = ",".join(interfaces.split(" "))
        params = {'-if': interfaces}
        if vendor:
            params['-vendor'] = vendor
        if port:
            params['-port'] = port
        self.enb_configuration_should_be_discovered(bts_id=bts_id, alias=alias)
        cta = self._get_emssim().cmd_cell_trace_activate()
        self._assert(cta.run(params), "Cell Trace activate operation failed")

    def cell_trace_format(self, trace_format=None, dump=None, dump_json=None, enb_id=None, bts_id=None, alias=None):
        """
        Set Cell Trace format

        :param trace_format: sequence (default) or detail
        :param dump: dump traces to text file (default=False)
        :param dump_json: dump traces to json file (default=False)
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +-------------------+----------------+
        |          Examples                  |
        +===================+================+
        | cell trace format | dump_json=True |
        +-------------------+----------------+
        """
        dump = self._opt_bool(dump)
        dump_json = self._opt_bool(dump_json)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        cmd = 'cell_trace_format'
        if trace_format is not None:
            if trace_format == 'sequence':
                cmd += ' -sequence'
            elif trace_format == 'detail':
                cmd += ' -detail'
            else:
                raise Exception("Wrong cell trace format: {}".format(trace_format))
        if dump:
            cmd += ' -dump 1'
        if dump_json:
            cmd += ' -dump_json 1'

        self.run_emssim_command(cmd)

    def cell_trace_deactivate(self, enb_id=None, bts_id=None, alias=None):
        """
        Deactivates Cell Trace on eNB

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +-----------------------+
        |       Examples        |
        +=======================+
        | cell trace deactivate |
        +-----------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self.enb_configuration_should_be_discovered(bts_id=bts_id, alias=alias)
        ctd = self._get_emssim().cmd_cell_trace_deactivate()
        self._assert(ctd.run(), "Cell Trace deactivate operation failed")

    def cell_trace_start(self, enb_id=None, bts_id=None, alias=None, callback=None):
        """
        Start Cell Trace reports collection

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss
        :param callback: python func invoked as callback when new data is received

        +------------------+
        |       Examples   |
        +==================+
        | cell trace start |
        +------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self._get_emssim().subscribe_events(event_type='cell_trace', callback=callback)

    def cell_trace_get(self, enb_id=None, bts_id=None, alias=None):
        """
        Get collected Cell Trace reports

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +---------------------------------+
        |       Examples                  |
        +=================================+
        | ${cell_traces}=  cell trace get |
        +---------------------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)
        return self._get_emssim().get_events(event_type='cell_trace')

    def cell_trace_wait(self, num=1, timeout=60, enb_id=None, bts_id=None, alias=None):
        """
        Wait for required number of Cell Trace reports

        :param num: Number of cell trace reports to wait for
        :param timeout: Wait until timeout (default=60 sec)
        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +-----------------+
        |       Examples  |
        +=================+
        | cell trace wait |
        +-----------------+
        """
        num = self._opt_int(num)
        timeout = self._opt_int(timeout)
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        print("Waiting for {} trace reports up to {} sec".format(num, timeout))
        traces = []
        wait_time = 0
        while wait_time < timeout:
            traces = self._get_emssim().get_events(event_type='cell_trace')
            if len(traces) >= num:
                break
            wait_time += 5
            time.sleep(5)
        else:
            self._assert(False, "Reguired number of Cell Traces did not appear before timeout ({})".format(len(traces)))
        return traces

    def cell_trace_clear(self, enb_id=None, bts_id=None, alias=None):
        """
        Clear collected Cell Trace reports

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +------------------+
        |       Examples   |
        +==================+
        | cell trace clear |
        +------------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self._get_emssim().clear_events(event_type='cell_trace')

    def cell_trace_stop(self, enb_id=None, bts_id=None, alias=None):
        """
        Stop Cell Traces collection and clear collected reports

        :param bts_id (enb_id): BTS instance ID
        :param alias: User defined alias used in setup_emss

        +-----------------+
        |       Examples  |
        +=================+
        | cell trace stop |
        +-----------------+
        """
        bts_id = self._opt_id(enb_id, bts_id)

        self = self._get_instance(bts_id, alias)

        self._get_emssim().unsubscribe_events(event_type='cell_trace')
